INSERT INTO `paket_wisata` (`id`, `judul`, `deskripsi`, `gambar`, `file_pdf`) VALUES
(13, 'Paket Wisata Bahari Kepulauan Sombori Morowali', 'Eksplorasi gugusan pulau karst, laguna biru kristal, Goa Berlian, Puncak Khayangan, dan wisata bawah laut Kepulauan Sombori Kabupaten Morowali.', '/images/PaketWisata/WISATA_SOMBORI.jpg', '/images/PaketWisata/pdf/Wisata_Bahari_Sombori.pdf'),
(14, 'Paket Wisata Megalith Taman Nasional Lore Lindu (TNLL)', 'Jelajah warisan purbakala Negeri Seribu Megalit di Lembah Bada, Besoa, dan Napu serta keanekaragaman hayati Cagar Biosfer UNESCO Taman Nasional Lore Lindu.', '/images/PaketWisata/tnll.jpg', '/images/PaketWisata/pdf/Paket_Wisata_Megalith_TNLL.pdf'),
(15, 'Prince John Dive Resort - Paket Wisata Selam Tanjung Karang Donggala', 'Paket wisata diving, snorkeling, dan resort tepi pantai berpasir putih di kawasan wisata bahari Tanjung Karang, Kabupaten Donggala.', '/images/PaketWisata/prince_john.jpg', '/images/PaketWisata/pdf/Prince_John_Dive_Resort.pdf'),
(16, 'Tour Packages Central Sulawesi - Pesona Destinasi Unggulan', 'Katalog resmi paket tur wisata terpadu menjelajahi destinasi alam, budaya, dan bahari unggulan di Provinsi Sulawesi Tengah.', '/images/PaketWisata/tour-packages-1_001.jpg', '/images/PaketWisata/pdf/Tour_Packages_Sulteng.pdf'),
(17, 'Profil & Paket Ekowisata Desa Wisata Malangga Tolitoli', 'Paket wisata alam pedesaan, air terjun, agrowisata, dan kearifan budaya lokal di Desa Wisata Malangga, Kabupaten Tolitoli.', '/images/PaketWisata/01_Desa_Malangga_002.jpg', '/images/PaketWisata/pdf/01_Desa_Malangga.pdf'),
(18, 'Brosur Paket Perjalanan Desa Wisata Malangga', 'Rincian itinerary dan paket aktivitas wisata keluarga serta petualangan alam di Desa Wisata Malangga.', '/images/PaketWisata/desa_malangga_paket.jpg', '/images/PaketWisata/pdf/Paket_Wisata_Desa_Malangga.pdf'),
(19, 'Paket Wisata Nusantara (PAK WISNU) Sulawesi Tengah', 'Program paket perjalanan wisata nusantara menyusuri ragam pesona bahari, pegunungan, dan kuliner khas Sulawesi Tengah.', '/images/PaketWisata/PAK_WISNU_000.jpg', '/images/PaketWisata/pdf/PAK_WISNU.pdf'),
(20, 'Paket Wisata Diving (Selam) Spot Terbaik Sulawesi Tengah', 'Paket penyelaman eksplorasi terumbu karang dan biota laut endemik di perairan Sulawesi Tengah.', '/images/PaketWisata/wisata_diving.jpg', '/images/PaketWisata/pdf/Paket_Wisata_Diving.pdf'),
(21, 'Paket Wisata Memancing (Fishing Tour) Sulawesi Tengah', 'Paket wisata minat khusus olahraga memancing (sport fishing) di perairan potensial Sulawesi Tengah.', '/images/PaketWisata/wisata_mancing.jpg', '/images/PaketWisata/pdf/Paket_Wisata_Memancing.pdf'),
(22, 'City Tour Package - Jelajah Wisata Kota Palu', 'Paket tur keliling Kota Palu mengunjungi ikon wisata sejarah, religi, kuliner Kaledo, sentra tenun Bomba, dan panorama Teluk Palu.', '/images/PaketWisata/paket_tour.jpg', '/images/PaketWisata/pdf/City_Tour_Package.pdf'),
(23, 'Paket Wisata Bahari Pusat Laut (Pusentasi) Donggala', 'Wisata keluarga dan bahari di sumur raksasa berair jernih alami Pusat Laut (Pusentasi) dan pesisir pantai Kabupaten Donggala.', '/images/PaketWisata/pusat_laut_-_preview.jpg', '/images/PaketWisata/pdf/Pusat_Laut_Donggala.pdf'),
(24, 'Paket Wisata Bahari Desa Wisata Mbuang-Mbuang Banggai Laut', 'Menjelajahi keindahan bawah laut, konservasi Banggai Cardinal Fish, dan wisata pulau eksotis di Desa Wisata Mbuang-Mbuang, Kabupaten Banggai Laut.', '/images/PaketWisata/mbuang-mbuang_-_preview.jpg', '/images/PaketWisata/pdf/Desa_Wisata_Mbuang_Mbuang.pdf'),
(25, 'Paket Wisata Sejarah & Budaya Kerajaan Banggai', 'Menelusuri jejak sejarah Keraton Kerajaan Banggai, budaya adat, dan peninggalan bersejarah di Kabupaten Banggai Laut.', '/images/PaketWisata/kerajaan_banggai_-_preview.jpg', '/images/PaketWisata/pdf/Wisata_Sejarah_Kerajaan_Banggai.pdf'),
(26, 'Explore Tana Taa - Paket Wisata Budaya & Alam Morowali Utara', 'Petualangan budaya Suku Wana (Tana Taa), cagar alam Morowali, dan pesona Teluk Tomori di Kabupaten Morowali Utara.', '/images/PaketWisata/explore_tana_taa.jpg', '/images/PaketWisata/pdf/Explore_Tana_Taa_Morowali_Utara.pdf'),
(27, 'Paket Wisata Kayak & Olahraga Air Bahari', 'Aktivitas wisata petualangan mendayung kayak menyusuri perairan tenang, hutan mangrove, dan pesisir pulau Sulawesi Tengah.', '/images/PaketWisata/kayak.jpg', '/images/PaketWisata/pdf/Paket_Wisata_Kayak_Bahari.pdf'),
(28, 'Paket Wisata Alam & Budaya Mataruttung', 'Paket perjalanan wisata eksplorasi keindahan alam, air terjun, dan tradisi masyarakat lokal di kawasan wisata Mataruttung.', '/images/PaketWisata/mataruttung.jpg', '/images/PaketWisata/pdf/Paket_Wisata_Mataruttung.pdf'),
(29, 'Paket Ekowisata Hutan & Tradisi Wana Posangke', 'Ekspedisi ekowisata hutan tropis dan pengenalan kehidupan harmonis masyarakat adat Wana Posangke.', '/images/PaketWisata/wana_posangke.jpg', '/images/PaketWisata/pdf/Paket_Wisata_Wana_Posangke.pdf'),
(30, 'Travel Guide Kabupaten Tolitoli', 'Buku panduan perjalanan wisata lengkap destinasi, akomodasi, kuliner, dan budaya di Kabupaten Tolitoli.', '/images/TRAVEL_GUIDE_001.jpg', '/images/Direktori/Leaflet_Palu1c.jpg'),
(31, 'Leaflet Panduan Wisata Kota Palu', 'Leaflet direktori peta wisata, destinasi unggulan, kuliner, dan akomodasi di Kota Palu.', '/images/Direktori/Leaflet_Palu1c.jpg', '/images/Direktori/Leaflet_Palu1c.jpg');
